<template>
  <DialogCard :config="dialogConfig.dialogData">
    <v-menu
      v-model="datePickerMenu"
      :close-on-content-click="false"
      max-width="290"
    >
      <template v-slot:activator="{ on, attrs }">
        <v-text-field
          :value="dateFormatted"
          :label="
            getTranslatedText('reportsView.printDailySummaryDialog.input')
          "
          readonly
          v-bind="attrs"
          v-on="on"
        />
      </template>
      <v-date-picker
        v-model="datePicker"
        no-title
        :first-day-of-week="1"
        :max="today"
        :locale="datePickerLocale"
        @change="datePickerMenu = false"
      />
    </v-menu>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import TTCONTROL_API_EVENTS from '@/config/events/serversAPI/ttcontrolEvents'
import PRINTER_EVENTS from '@/config/events/printer'

import { getTodayForReports, getDateWithFormat } from '@/tools/dates'
import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import reportsViewActions from '@/store/reportsView/actions.types'

import setConfig from '@/components/ReportsView/PrintDailySummaryDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'PrintDailySummaryDialog',
  components: { DialogCard },
  data() {
    return {
      datePicker: getTodayForReports(),
      today: getTodayForReports(),
      datePickerMenu: false,
    }
  },
  computed: {
    ...mapState('reportsView', ['printDailySummaryDialog']),
    ...mapState('app', ['addMarginTicket']),
    ...mapState('account', ['data']),
    dialogConfig() {
      return setConfig(
        { isOpen: this.printDailySummaryDialog },
        {
          closeDialog: this.closeDialog,
          printSummary: this.getPrintDailySummary,
        }
      )
    },
    datePickerLocale() {
      return `${this.data.country.language}-${this.data.country.localeIsoCode}`
    },
    dateFormatted() {
      return getDateWithFormat(this.datePicker, 'DD-MM-YYYY')
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('reportsView', [
      reportsViewActions.setPrintDailySummaryDialog,
    ]),
    closeDialog() {
      this[reportsViewActions.setPrintDailySummaryDialog]({
        isOpen: false,
      })
    },
    getPrintDailySummary() {
      rendererEventsService.send(TTCONTROL_API_EVENTS.channel, {
        event: TTCONTROL_API_EVENTS.events.getDailySummaryToPrint.name,
        data: {
          pos: this.data.pos,
          date: this.datePicker,
        },
      })
      this.$loading.show('printDailySummary')
    },
  },
  created() {
    rendererEventsService.subscribe(
      TTCONTROL_API_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [TTCONTROL_API_EVENTS.events.getDailySummaryToPrint.replies
            .success]: () => {
            rendererEventsService.send(PRINTER_EVENTS.channel, {
              event: PRINTER_EVENTS.events.printSale.name,
              data: {
                ticketToPrint: payload.htmlToPrint,
                addMarginTicket: this.addMarginTicket,
              },
            })
            this.$loading.hide()
            notificationsService.showSuccess(
              'reportsView.printDailySummaryDialog.successNotification',
              this.$vuetify.lang
            )
            this.closeDialog()
          },
          [TTCONTROL_API_EVENTS.events.getDailySummaryToPrint.replies
            .error]: () => {
            this.$loading.hide()
            notificationsService.showError(
              'reportsView.printDailySummaryDialog.errorNotification',
              this.$vuetify.lang
            )
            this.closeDialog()
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(TTCONTROL_API_EVENTS.replyChannel)
  },
}
</script>
