<template>
  <div v-if="hasReportsEnabled" class="fill-height pa-3">
    <div id="reports-header">
      <section
        class="px-3 py-1 mb-3 d-flex align-center google-play-banner googleBanner"
      >
        <a :href="getTTControlPlayStore" target="_blank">
          <img
            :src="require(`../../assets/badgets/${getLocaleBadge}.png`)"
            height="61"
          />
        </a>
        <span class="align-self-center textBanner--text">
          <b>{{ $vuetify.lang.t(`$vuetify.reportsView.introduction.1`) }}</b>
          {{ $vuetify.lang.t(`$vuetify.reportsView.introduction.2`) }}
          <b>{{ $vuetify.lang.t(`$vuetify.reportsView.introduction.3`) }}</b>
          {{ $vuetify.lang.t(`$vuetify.reportsView.introduction.4`) }}
        </span>
      </section>
      <div class="d-flex align-center justify-space-between pl-3 pt-2 pb-6">
        <div class="d-flex">
          <v-icon color="primary" large>mdi-chart-line</v-icon>
          <FormattedText
            intl
            type="text-h6"
            color="textPrimary"
            value="mainLayout.navigation.reports"
            class="pl-2"
          />
        </div>
        <div class="d-flex">
          <ButtonDropdown
            fab
            depressed
            dark
            small
            class="mr-1"
            id="help-dropdown-control"
            label="productsView.toolbar.buttons.help"
            icon="mdi-school"
            color="help"
            textColor="textPrimary"
            :items="getFilteredData"
            listItemType="VideoListItem"
          />
          <Button
            v-if="isInternet"
            class="px-1"
            tooltipPosition="bottom"
            fab
            dark
            small
            depressed
            color="accent"
            icon="mdi-cloud-print-outline"
            tooltipText="reportsView.printDailySummaryDialog.title"
            id="print-daily-summary"
            @click="openPrintDailySummaryDialog()"
          />
        </div>
      </div>
      <v-alert dense color="primary" border="left" colored-border class="ml-4">
        <FormattedText
          intl
          color="textBanner"
          value="reportsView.information"
        />
      </v-alert>
    </div>
    <div v-if="isInternet" class="fill-height d-flex justify-center">
      <iframe
        :src="getTTControlUrl"
        width="992"
        :height="`${iframeHeight}px`"
        frameborder="0"
      />
    </div>
    <div v-else class="no-internet-section">
      <HelpWatermark :config="noConnection" class="align-center" />
    </div>
    <PrintDailySummaryDialog v-if="printDailySummaryDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex'
import axios from 'axios'

import { ttcontrolURL, ttcontrolPlayStore } from '@/config/env'
import helpCategories from '@/config/helpCategories'

import { captureMessage } from '@/tools/exceptions'

import i18n from '@/plugins/i18n'

import helpCenterViewActions from '@/store/helpCenterView/actions.types'
import reportsViewActions from '@/store/reportsView/actions.types'

import ButtonDropdown from '@/components/shared/ButtonDropdown'
import FormattedText from '@/components/shared/FormattedText'
import HelpWatermark from '@/components/shared/HelpWatermark'
import Button from '@/components/shared/CustomButton'
import PrintDailySummaryDialog from '@/components/ReportsView/PrintDailySummaryDialog'

export default {
  name: 'Reports',
  components: {
    FormattedText,
    ButtonDropdown,
    HelpWatermark,
    Button,
    PrintDailySummaryDialog,
  },
  data() {
    return {
      isInternet: navigator.onLine,
      noConnection: {
        icon: 'mdi-cloud-off-outline',
        messages: ['notification.helpCenter.internetConnectionError'],
      },
      iframeHeight: null,
    }
  },
  computed: {
    ...mapState('account', ['data']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('app', ['windowSize']),
    ...mapState('reportsView', ['printDailySummaryDialog']),
    ...mapGetters('helpCenter', ['getFilteredData']),
    getTTControlUrl() {
      return `${ttcontrolURL}/duenotek/${this.data.pos}?browser_type=5`
    },
    getTTControlPlayStore() {
      return ttcontrolPlayStore
    },
    getLocaleBadge() {
      return i18n.locale == 'es'
        ? 'google-play-badge-es'
        : 'google-play-badge-en'
    },
    hasReportsEnabled() {
      return this.selectedUser.reportPermission === 0
    },
  },
  methods: {
    ...mapActions('helpCenterView', [helpCenterViewActions.setVideoTypeFilter]),
    ...mapActions('reportsView', [
      reportsViewActions.setPrintDailySummaryDialog,
    ]),
    updateIframeHeight(windowHeight) {
      const headerHeight = document.getElementById('reports-header')
        .clientHeight
      this.iframeHeight = windowHeight - headerHeight - 125
    },
    openPrintDailySummaryDialog() {
      this[reportsViewActions.setPrintDailySummaryDialog]({ isOpen: true })
    },
  },
  watch: {
    windowSize(newSize) {
      this.updateIframeHeight(newSize.y)
    },
  },
  mounted() {
    this[helpCenterViewActions.setVideoTypeFilter]([helpCategories.reports])
    // To capture LetsEncrypt certs problems
    axios
      .get(`${ttcontrolURL}/duenotek/${this.data.pos}?browser_type=5`)
      .catch(error => captureMessage(`TTControl - ${error}`))
    this.updateIframeHeight(this.windowSize.y)
  },
  beforeDestroy() {
    this[helpCenterViewActions.setVideoTypeFilter]([])
  },
}
</script>

<style lang="scss" scoped>
.google-play-banner {
  border-radius: 25px;
}

.theme--dark.v-sheet {
  background-color: transparent;
}

.no-internet-section {
  display: flex;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  margin-top: 25vh;
}
</style>
