const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-cloud-print-outline',
    title: 'reportsView.printDailySummaryDialog.title',
    messages: ['reportsView.printDailySummaryDialog.message'],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 325,
    maxWidth: 500,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.printSummary(),
  },
})

export default setConfig
